import {adventureHost,configureHostedWorld} from '../shared/adventure-host.js';
import {bindControls,createAudio,writeSaved,registerAdventure,backToArcade} from '../shared/runtime.js';
import {KEY,VOCAB,FACTS,CONCEPTS,QUESTIONS,LEVELS,shuffle,fresh,load,recordQuestion,practiceKeys,QUESTION_KEYS,emptyRecord} from './science.js';
import {makeWorld,newPlayer,updatePhysics} from './world.js';
import {titleArt,drawWorld} from './art.js';
import {picture,demoMarkup,dipperSvg} from './pictures.js';
const $=id=>document.getElementById(id),c=$('game'),ctx=c.getContext('2d'),overlay=$('overlay');
let progress;try{progress=load(localStorage);}catch{progress=fresh();}
let controls=null,frameId=0,disposed=false;
let mode='menu',world=null,player=null,camera=0,checkpoint=100,time=0,last=performance.now(),acc=0,effects=[],noticeUntil=0,nextHud=0;
let input={left:false,right:false,jump:false},pointers=new Map(),keys=new Set(),station=null,queue=[],question=null,demo=null,practicePool=[],practiceCount=0,practiceTotal=0,practiceBatch=0,audio=null;
const on=(id,fn)=>$(id)?.addEventListener('click',fn);
function save(){try{if(!writeSaved(localStorage,KEY,progress))throw Error();$('save-warning').hidden=true;}catch{$('save-warning').hidden=false;}}
function saveRun(){if(world&&player&&progress.run){Object.assign(progress.run,{level:world.index,checkpoint,done:world.stations.filter(s=>s.done).map(s=>s.id),taken:world.crystals.filter(s=>s.taken).map(s=>s.id),night:!!world.night});save();}}
function clearInput(){controls?.clear();input={left:false,right:false,jump:false};}
function setMode(m){mode=m;clearInput();$('controls').hidden=m!=='play';$('hud').hidden=!['play','pause','question','demo'].includes(m)||!progress.run;$('action').hidden=true;$('toast').classList.remove('visible');try{speechSynthesis.cancel();}catch{}}
function show(html){overlay.innerHTML=html;}
function toast(s,seconds=4){$('toast').textContent='BEEP: '+s;noticeUntil=time+seconds;$('toast').classList.add('visible');}
function say(text){if(!progress.narration){toast('Voice is off. Turn it on to listen.');return;}if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){toast('Read-aloud is unavailable here. A grown-up can read with you.');return;}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.82;u.pitch=1.1;u.lang='en-US';speechSynthesis.speak(u);}catch{}}
const audioEngine=createAudio({jump:[300,440],star:[740,1000],good:[523,659,784],retry:[240,210],win:[523,659,784,1047]});
function sfx(kind){audioEngine.play(kind,progress.sound);}
function spark(x,y){for(let i=0;i<20;i++)effects.push({x,y,vx:(Math.random()-.5)*180,vy:-80-Math.random()*180,life:1,color:['#ffe18c','#a8ecdf','#c9b8ff'][i%3]});}
function toggleSound(){progress.sound=!progress.sound;save();$('sound').textContent=progress.sound?'♪ ON':'♪ OFF';if($('menu-sound'))$('menu-sound').textContent=`Sound ${progress.sound?'on':'off'}`;sfx('good');}
on('sound',toggleSound);
function menu(){station=null;setMode('menu');show(`<section class="title-screen space-title"><p class="eyebrow">LUMINARA • BEEP’S SPACE ADVENTURE</p><h1>STAR<span>QUEST</span></h1><p class="subtitle">The Missing North Star!</p><p class="story">Three crystals. One lost star.<br>Ready to save the night sky, explorer?</p><div class="menu-buttons"><button class="primary" id="play">${progress.run?'CONTINUE ADVENTURE':'PLAY ADVENTURE'} ➜</button><button class="secondary" id="practice">PRACTICE FOR MY TEST</button><button class="secondary" id="mistakes">PRACTICE MY MISTAKES</button><button class="secondary" id="parent">PARENT PROGRESS</button></div>${progress.run?'<button class="new-run text-btn" id="new-adventure">PLAY ADVENTURE AGAIN</button>':''}<div class="menu-footer"><button class="text-btn" id="menu-sound">Sound ${progress.sound?'on':'off'}</button><button class="text-btn" id="voice">Voice ${progress.narration?'on':'off'}</button><button class="text-btn" id="easy">Easy Touch ${progress.easy?'on':'off'}</button><button class="text-btn" id="help">How to play</button><button class="text-btn" id="back-arcade">Back to Arcade</button></div></section>`);on('play',()=>progress.run?startLevel(progress.run.level):intro());on('practice',practiceMenu);on('mistakes',()=>startPractice(true));on('parent',dashboard);on('menu-sound',toggleSound);on('voice',()=>{progress.narration=!progress.narration;save();menu();});on('easy',()=>{progress.easy=!progress.easy;save();menu();});on('help',help);on('back-arcade',backToArcade);on('new-adventure',intro);}
function intro(){setMode('intro');show(`<section class="panel"><p class="eyebrow">HELLO, JUNIOR EXPLORER!</p><h2>The North Star is missing!</h2><div class="shape-pair">${picture('earth')}${picture('moon')}${picture('star')}</div><p>I’m Beep! Find three Star Crystals with me.<br>We’ll help our friends find home!</p><button class="secondary" id="read-intro">🔊 HEAR BEEP</button><div class="row"><button class="primary" id="begin">LET’S GO, EXPLORER! ➜</button><button class="secondary" id="back">BACK</button></div></section>`);on('read-intro',()=>say('Hello, explorer! I am Beep. The North Star is missing! Find three Star Crystals with me. Let’s save the night sky!'));on('back',menu);on('begin',()=>{progress.run={level:0,checkpoint:100,done:[],taken:[],stars:0,score:0,crystals:[],observatory:0,answers:{},night:false};save();startLevel(0);});}
function startLevel(index){world=configureHostedWorld(makeWorld(index));const r=progress.run;checkpoint=r.checkpoint;player=newPlayer(checkpoint,460);player.checkpoint=checkpoint;world.night=r.night;world.stations.forEach(s=>s.done=r.done.includes(s.id));world.crystals.forEach(s=>s.taken=r.taken.includes(s.id));camera=Math.max(0,Math.min(5000,checkpoint-350));effects=[];show('');setMode('play');hud();toast(['Let’s spin into action!','Moon boots? Check! Bouncy knees? Check!','Let’s bring back our guiding star!'][index],5);saveRun();const pending=adventureHost()?.pendingStation;if(pending){station=world.stations.find(s=>s.id===pending);if(station)nextQuestion();}}
function hud(){if(!world||!progress.run)return;$('stars').textContent=`★ ${progress.run.stars}`;$('crystals').textContent=`◆ ${progress.run.crystals.length}/3`;$('chapter').textContent=`MISSION ${world.index+1} / 3${progress.easy?' • EASY TOUCH':''}`;$('level-name').textContent=adventureHost()?.stageName||LEVELS[world.index].short;$('progress-fill').style.width=Math.min(100,player.x/5950*100)+'%';$('sound').textContent=progress.sound?'♪ ON':'♪ OFF';}
function help(){setMode('help');show(`<section class="panel"><h2>You’re in charge, explorer!</h2><p>Hold ◀ or ▶ to move.<br>Tap ↑ to jump. Use both thumbs!</p><p>Tap ✦ DISCOVER by Beep’s machines.<br>Two quick questions, then back to exploring!<br>Tap 🔊 to listen. TRY IT opens an optional discovery.</p><p><strong>Easy Touch:</strong> tap an arrow to keep going. Tap it again to stop. Small gaps get an automatic jump. Tap Jump any time!</p><p>Flags save your place. Falling brings you back.<br>Computer: arrows / A / D, Space to jump, E to discover, Esc to pause.</p><button class="primary" id="back">GOT IT!</button></section>`);on('back',menu);}
function pause(){if(mode!=='play')return;saveRun();setMode('pause');show(`<section class="panel"><h2>Space snack break!</h2><p>Your flag is saved. Beep can wait.</p><div class="row"><button class="primary" id="resume">KEEP EXPLORING</button><button class="secondary" id="home">MAIN MENU</button></div><button class="text-btn" id="easy-pause">Easy Touch ${progress.easy?'on':'off'}</button></section>`);on('resume',()=>{show('');setMode('play');});on('home',menu);on('easy-pause',()=>{progress.easy=!progress.easy;save();$('easy-pause').textContent=`Easy Touch ${progress.easy?'on':'off'}`;});}
on('pause',pause);
function nearby(){return world?.stations.find(s=>!s.done&&Math.abs(player.x-s.x)<132&&player.y>380);}
function interact(){if(mode!=='play')return;station=nearby();if(!station)return;queue=[...station.terms];if(station.type==='final')progress.run.observatory=0;sfx('good');nextQuestion();}
function nextQuestion(){const host=adventureHost();if(host){setMode('question');show('');queue=[];host.challenge(station.id,2,()=>{if(station.type==='final')progress.run.observatory=station.terms.length;completeStation();});return;}const id=queue.shift();if(!id){completeStation();return;}present(id,false);}
function present(id,practicing){question={key:id,data:QUESTIONS[id],attempt:0,solved:false,practicing};if(practicing&&question.data.demo){startDemo(question.data.demo,()=>renderQuestion());}else renderQuestion();}
function startDemo(kind,done){setMode('demo');demo={kind,step:0,done,selected:null,placed:0};renderDemo();}
function renderDemo(){const d=demo;const directions=['rise','set'].includes(d.kind);const labels={clock:'Tap the clock! One whole day.',spin:'Tap Earth to spin!',light:'Tap the Sun. Watch the explorer turn!',night:'Turn Earth. Find your nighttime!',orbit:'Tap to move Earth around the Sun!',moonOrbit:'Tap to move the Moon!',phases:'Tap to change the Moon’s look!',sphere:'Tap the ball to turn it!',sun:'Tap the Sun to light Earth!',daystars:'Tap to switch day and night!',pointers:'Tap the two golden pointer stars!',north:'Tap the pointers. Follow the line!',rise:'Match morning and evening.',set:'Match morning and evening.'};show(`<section class="panel demo-panel"><p class="eyebrow">BEEP’S DISCOVERY LAB</p><h2>${labels[d.kind]||'Tap and discover!'}</h2><button class="demo-object" id="demo-tap" aria-label="Interact with ${d.kind}">${demoMarkup(d.kind,d.step)}</button>${directions?`<div class="direction-place"><div><button class="secondary" id="select-east">EAST</button><button class="secondary" id="select-west">WEST</button></div><div><button class="answer" id="place-rise">Sunrise ${d.placed>=1?'✓':'?'}</button><button class="answer" id="place-set">Sunset ${d.placed>=2?'✓':'?'}</button></div><p id="place-note">Tap EAST or WEST. Then tap a place.</p></div>`:''}<p id="demo-note">${d.step?'Nice exploring! '+(d.kind==='phases'?'The Moon stays round. We see different amounts of its sunlit half.':''):d.kind==='north'?'The golden stars are the outside edge of the bowl.':'Tap the picture to try it.'}</p><div class="row"><button class="secondary" id="read-demo">🔊 SPEAK ALOUD</button><button class="primary" id="demo-next" ${(directions?d.placed<2:d.step<1)?'disabled':''}>I’M READY! ➜</button></div></section>`);on('demo-tap',()=>{d.step++;if(world&&['spin','light','night'].includes(d.kind))world.night=d.step%2===1;renderDemo();sfx('star');});on('read-demo',()=>say((labels[d.kind]||'Tap and discover')+' '+(d.kind==='phases'?'The Moon stays round. We see different amounts of its sunlit half.':d.kind==='pointers'||d.kind==='north'?'The two stars on the outside edge of the bowl point to the North Star.':'')));on('demo-next',()=>d.done());
 if(directions){on('select-east',()=>{d.selected='east';$('place-note').textContent='EAST selected. Tap Sunrise or Sunset.';say('East');});on('select-west',()=>{d.selected='west';$('place-note').textContent='WEST selected. Tap Sunrise or Sunset.';say('West');});for(const [id,want,stage]of [['place-rise','east',1],['place-set','west',2]])on(id,()=>{if(d.selected===want&&d.placed===stage-1){d.placed=stage;d.step=stage-1;renderDemo();sfx('good');}else $('place-note').textContent=d.selected?'Try another match. Start with Sunrise.':'Choose EAST or WEST first.';});}}
function renderQuestion(){setMode('question');const q=question.data;const demoKind=q.demo||(q.id==='phases'?'phases':null)||(!question.practicing&&(station?.type==='final'?'clock':station?.type));const options=shuffle(q.answers.map(([label,pic],index)=>({label,pic,index})));const scene=q.art==='north'?dipperSvg(true,true):q.art==='dipper'?dipperSvg():['daynight','orbit','moonOrbit','phases','directions','clock'].includes(q.art)?demoMarkup(q.art==='daynight'?'light':q.art==='directions'?'rise':q.art,1):'';show(`<section class="panel question star-question"><div class="question-top"><span class="eyebrow">${question.practicing?`PRACTICE ${practiceCount+1} / ${practiceTotal}`:station?.type==='final'?`STAR BRIGHTNESS ${progress.run.observatory} / ${station.terms.length}`:(station?.name?station.name+' • '+(station.terms.length-queue.length)+' / '+station.terms.length:'BEEP’S QUESTION')}</span><button class="text-btn" id="voice-question">Voice ${progress.narration?'on':'off'}</button></div><h2>${q.prompt}</h2>${scene?`<div class="question-scene">${scene}</div>`:''}<div class="question-tools"><button class="read-question secondary" id="read-question">🔊 SPEAK ALOUD</button>${!question.practicing&&demoKind?'<button class="read-question secondary" id="try-demo">TRY IT ✦</button>':''}</div><div class="picture-answers">${options.map(o=>`<div class="choice-wrap"><button class="answer picture-answer" data-choice="${o.index}">${picture(o.pic)}<span>${o.label}</span></button><button class="choice-speak" data-speak="${o.index}" aria-label="Read choice: ${o.label}">🔊</button></div>`).join('')}</div><p class="feedback" id="feedback" aria-live="polite">Tap a picture. Take your time!</p><div class="row"><button class="primary" id="question-next" hidden>${!question.practicing&&queue.length===0?'BACK TO ADVENTURE! ➜':'KEEP GOING! ➜'}</button></div></section>`);document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>answer(Number(b.dataset.choice),b)));document.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>say(q.answers[Number(b.dataset.speak)][0])));on('read-question',()=>say(q.prompt+'. '+options.map((o,i)=>`Choice ${i+1}. ${o.label}`).join('. ')));on('voice-question',()=>{progress.narration=!progress.narration;save();$('voice-question').textContent=`Voice ${progress.narration?'on':'off'}`;try{speechSynthesis.cancel();}catch{}});on('try-demo',()=>{if(!question.solved)startDemo(demoKind,()=>renderQuestion());});on('question-next',()=>question.practicing?nextPractice():nextQuestion());}
function answer(index,button){if(question.solved)return;const q=question.data,correct=index===q.correct;say(q.answers[index][0]+(correct?'. '+q.explain:''));recordQuestion(progress,question.key,correct,question.attempt);if(progress.run&&!question.practicing){progress.run.itemAnswers??={};if(progress.run.itemAnswers[question.key]===undefined)progress.run.itemAnswers[question.key]=correct;}if(progress.run&&!question.practicing&&progress.run.answers[q.id]===undefined)progress.run.answers[q.id]=correct;question.attempt++;save();if(!correct){button.classList.add('wrong');button.disabled=true;$('feedback').textContent='Try again! '+q.hint;sfx('retry');return;}question.solved=true;if($('try-demo'))$('try-demo').hidden=true;button.classList.add('correct');document.querySelectorAll('[data-choice]').forEach(b=>b.disabled=true);$('feedback').textContent=(question.attempt===1?'You got it! ':'Good trying! ')+q.explain;$('question-next').hidden=false;sfx('good');if(progress.run&&!question.practicing){progress.run.stars+=2;progress.run.score+=question.attempt===1?100:35;if(station.type==='final')progress.run.observatory++;saveRun();hud();}if(question.practicing){practiceCount++;practiceBatch++;}}
function completeStation(){station.done=true;station.activated=world.time;checkpoint=station.x+65;player.checkpoint=checkpoint;player.x=Math.max(player.x,station.x-30);if(world.index===2&&station.type==='pointers'&&!progress.run.crystals.includes('Night Sky'))progress.run.crystals.push('Night Sky');spark(station.x,430);saveRun();show('');setMode('play');toast(station.type==='final'?'You did it! Follow the shining star to the exit.':'Discovery complete! Your path is open.');station=null;hud();}
function endLevel(){if(adventureHost()){setMode('level');saveRun();adventureHost().complete();return;}if(world.index===2){win();return;}const name=LEVELS[world.index].crystal;if(!progress.run.crystals.includes(name))progress.run.crystals.push(name);saveRun();setMode('level');sfx('win');show(`<section class="panel"><p class="eyebrow">MISSION COMPLETE!</p><div class="crystal-reward">◆</div><h2>${name} Star Crystal!</h2><p>${world.index===0?'Next stop: the Moon! Boing, boing!':'Next stop: the night sky!'}</p><button class="primary" id="next-level">LET’S GO! ➜</button></section>`);on('next-level',()=>{Object.assign(progress.run,{level:world.index+1,checkpoint:100,done:[],taken:[],night:false});save();startLevel(progress.run.level);});}
function win(){progress.run.won=true;const itemAnswers=progress.run.itemAnswers||progress.run.answers;const first=Object.values(itemAnswers).filter(Boolean).length;progress.lastResult={stars:progress.run.stars,score:progress.run.score,first,total:Object.keys(itemAnswers).length,crystals:[...progress.run.crystals]};progress.run=null;save();victory();}
function victory(){setMode('victory');sfx('win');const r=progress.lastResult;show(`<section class="panel"><p class="eyebrow">YOU SAVED THE NIGHT SKY!</p><div class="trophy">🏆</div><h2>Junior Space Explorer!</h2><p>The North Star shines again.<br>Beep says: “You’re out of this world!”</p><div class="stars">★ ★ ★</div><div class="stats-grid"><div class="stat"><strong>${r.stars}</strong>STARS + ROCKS</div><div class="stat"><strong>3/3</strong>STAR CRYSTALS</div><div class="stat"><strong>${r.first}/${r.total||20}</strong>FIRST TRY</div><div class="stat"><strong>${r.score}</strong>SCORE</div></div><div class="row"><button class="primary" id="again">PLAY AGAIN</button><button class="secondary" id="review">PRACTICE MY MISTAKES</button><button class="secondary" id="home">MAIN MENU</button></div></section>`);on('again',intro);on('review',()=>startPractice(true));on('home',menu);}
function practiceMenu(){setMode('practice-menu');show(`<section class="panel"><p class="eyebrow">PRACTICE FOR MY TEST</p><h2>Little practice. Big discoveries!</h2><p>Five short activities at a time.</p><div class="menu-stack"><button class="primary" id="all">PRACTICE EVERYTHING</button><button class="secondary" id="missed">PRACTICE MY MISTAKES</button><button class="secondary" id="words">STUDY MY WORDS</button><button class="secondary" id="again">PLAY ADVENTURE AGAIN</button><button class="text-btn" id="home">MAIN MENU</button></div></section>`);on('all',()=>startPractice(false));on('missed',()=>startPractice(true));on('words',()=>study(0,false));on('again',intro);on('home',menu);}
function startPractice(missed){station=null;practicePool=shuffle(practiceKeys(progress,missed));practiceTotal=practicePool.length;practiceCount=0;practiceBatch=0;nextPractice();}
function nextPractice(){if(!practicePool.length||practiceBatch>=5){setMode('practice-result');show(`<section class="panel"><div class="crystal-reward">✦</div><h2>${practiceCount?'Good exploring, explorer!':'No tricky words waiting!'}</h2><p>${practiceCount?`${practiceCount} / ${practiceTotal} activities practiced.`:'Play or practice everything to fill your journal.'}</p><div class="row">${practicePool.length?'<button class="primary" id="more">NEXT FIVE</button>':'<button class="primary" id="all">PRACTICE EVERYTHING</button>'}<button class="secondary" id="home">MAIN MENU</button></div></section>`);on('more',()=>{practiceBatch=0;nextPractice();});on('all',()=>startPractice(false));on('home',menu);return;}present(practicePool.shift(),true);}
function study(index,flipped){setMode('study');const v=VOCAB[index];show(`<section class="panel study-panel"><p class="eyebrow">MY STUDY WORDS • ${index+1} / 9</p><button class="flashcard ${flipped?'definition':''}" id="flip">${flipped?v.definition:v.term}<small>TAP TO FLIP</small></button><div class="row"><button class="secondary" id="prev">← PREVIOUS</button><button class="secondary" id="read-word">🔊 READ</button><button class="secondary" id="next">NEXT →</button></div><button class="text-btn" id="home">BACK TO PRACTICE</button></section>`);on('flip',()=>study(index,!flipped));on('prev',()=>study((index+8)%9,false));on('next',()=>study((index+1)%9,false));on('read-word',()=>say(v.term+'. '+v.definition));on('home',practiceMenu);}
function dashboard(){setMode('parent');const rows=concepts=>concepts.map(c=>{const s=progress.stats[c.id];return `<tr><td><strong>${c.kind==='Word'?c.term:c.definition}</strong>${c.kind==='Word'?'<br>'+c.definition:''}</td><td>${s.encounters?'Yes':'No'}</td><td>${s.firstCorrect}/${s.encounters}${s.encounters?' • '+Math.round(s.firstCorrect/s.encounters*100)+'%':''}</td><td>${s.mistakes}</td><td>${s.needsReview?'Practice':s.correct?'✓ Latest first try':'Not assessed'}</td><td>${s.latest}</td></tr>`;}).join('');show(`<section class="panel parent-panel"><p class="eyebrow">PARENT LEARNING JOURNAL</p><h2>Luminara science progress</h2><p>First try accuracy counts each fresh question encounter. Correct after a retry stays marked for review. A fresh first-try answer clears that question’s flag. A topic stays flagged while any of its small facts need practice. Self-study does not award mastery.</p><div class="table-scroll"><table id="concept-progress"><thead><tr><th>Concept</th><th>Practiced</th><th>First try</th><th>Mistakes</th><th>Review</th><th>Latest result</th></tr></thead><tbody><tr><th colspan="6">9 vocabulary words</th></tr>${rows(VOCAB)}<tr><th colspan="6">11 test facts</th></tr>${rows(FACTS)}</tbody></table></div><details class="question-details"><summary>Small-fact question progress (${QUESTION_KEYS.length} questions)</summary><div class="table-scroll"><table id="question-progress"><thead><tr><th>Question</th><th>First try</th><th>Mistakes</th><th>Review</th></tr></thead><tbody>${QUESTION_KEYS.map(key=>{const t=progress.items?.[key]||emptyRecord();return `<tr><td>${QUESTIONS[key].prompt}</td><td>${t.firstCorrect}/${t.encounters}</td><td>${t.mistakes}</td><td>${t.needsReview?'Practice':t.correct?'✓':'Not practiced'}</td></tr>`;}).join('')}</tbody></table></div></details><div class="row"><button class="primary" id="home">MAIN MENU</button><button class="secondary" id="reset">RESET PROGRESS</button></div></section>`);on('home',menu);on('reset',parentCheck);}
function parentCheck(){show(`<section class="panel"><h2>Grown-up check</h2><p>What is 9 + 7?</p><div class="row"><button class="secondary" id="wrong9">9</button><button class="secondary" id="right16">16</button><button class="secondary" id="wrong24">24</button></div><p id="reset-note">A grown-up can reset this game’s journal.</p><button class="text-btn" id="back">CANCEL</button></section>`);on('back',dashboard);for(const id of ['wrong9','wrong24'])on(id,()=>{$('reset-note').textContent='Please ask a grown-up.';});on('right16',()=>{show(`<section class="panel"><h2>Clear Star Quest progress?</h2><p>This clears your adventure and learning journal on this device.</p><div class="row"><button class="secondary" id="cancel">KEEP PROGRESS</button><button class="primary" id="confirm">RESET STAR QUEST</button></div></section>`);on('cancel',dashboard);on('confirm',()=>{progress=fresh();world=null;player=null;save();menu();});});}
controls=bindControls({getState:()=>input,isPlaying:()=>mode==='play',easy:()=>progress.easy,interact,escape:()=>{if(mode==='play')pause();else if(mode==='pause')$('resume').click();}});
window.addEventListener('blur',()=>{clearInput();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();pause();saveRun();try{speechSynthesis.cancel();}catch{}}});window.addEventListener('pagehide',saveRun);window.addEventListener('resize',()=>{if(innerHeight>innerWidth){clearInput();pause();}resize();});document.addEventListener('contextmenu',e=>e.preventDefault());
function resize(){const r=c.getBoundingClientRect(),s=Math.min(2,r.width/1200*Math.min(2,devicePixelRatio||1));c.width=Math.round(1200*s);c.height=Math.round(720*s);ctx.setTransform(c.width/1200,0,0,c.height/720,0,0);}
function tick(dt){if(mode!=='play')return;if(innerHeight>innerWidth){pause();return;}if(progress.easy&&player.grounded){const ahead=player.x+(input.right?80:input.left?-40:0);if((input.right||input.left)&&world.gaps.some(([a,b])=>ahead>a&&ahead<b))input.jump=true;}const f={...input};input.jump=false;const fell=updatePhysics(player,world,f,dt);if(f.didJump)sfx('jump');if(fell){player.x=checkpoint;player.y=450;player.vx=player.vy=0;player.hurt=1.5;clearInput();toast('Soft landing! Your stars are safe.');}for(const x of [2250,3950,5650])if(player.x>=x&&checkpoint<x){checkpoint=x;player.checkpoint=x;saveRun();toast('Flag saved! Space high five!');}for(const v of world.crystals)if(!v.taken&&Math.abs(player.x+16-v.x)<31&&Math.abs(player.y+26-v.y)<47){v.taken=true;progress.run.stars+=v.bonus?5:1;progress.run.score+=v.bonus?40:10;spark(v.x,v.y);sfx('star');saveRun();}const near=nearby();$('action').hidden=!near;if(near)$('action').textContent=near.type==='final'?'✦ RESTORE THE STAR':'✦ DISCOVER';camera+=(Math.max(0,Math.min(5000,player.x-390))-camera)*Math.min(1,dt*7);if(player.x>5850&&world.stations.every(s=>s.done))endLevel();if(time>nextHud){hud();nextHud=time+.1;}}
function frame(now){if(disposed)return;let dt=Math.min(.05,(now-last)/1000);last=now;time+=dt;acc+=dt;while(acc>=1/120){tick(1/120);acc-=1/120;}for(const e of effects){e.life-=dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vy+=300*dt;}effects=effects.filter(e=>e.life>0);if(world&&['play','pause','question','demo','level','victory'].includes(mode))drawWorld(ctx,world,player,camera,time,effects,progress.run||{won:true,observatory:6});else titleArt(ctx,time);if(time>noticeUntil)$('toast').classList.remove('visible');frameId=requestAnimationFrame(frame);}
resize();menu();frameId=requestAnimationFrame(frame);registerAdventure({player:'kal',save:()=>{if(progress.run&&world)saveRun();else save();},stop:async()=>{disposed=true;cancelAnimationFrame(frameId);controls.destroy();await audioEngine.close();try{speechSynthesis.cancel();}catch{}}});
Object.defineProperty(window,'starQuest',{get:()=>JSON.parse(JSON.stringify({mode,player,checkpoint,world:world?{index:world.index,stations:world.stations,crystals:world.crystals,platforms:world.platforms}:null,question:question?{key:question.key,id:question.data.id,attempt:question.attempt,correct:question.data.correct,solved:question.solved}:null,demo:demo?{kind:demo.kind,step:demo.step,placed:demo.placed}:null,input,progress}))});
